import{_ as e,o as a,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Número do processo no menu superior","description":"","frontmatter":{"title":"Número do processo no menu superior","id":"eproc-numero-processo-navbar","plataforma":"eproc","grupo":"Menu superior","plano":"free","desde":"1.3.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-numero-processo-navbar.md","filePath":"funcionalidades/eproc-numero-processo-navbar.md"}'),t={name:"funcionalidades/eproc-numero-processo-navbar.md"};function n(i,o,d,p,l,u){return a(),r("div",null,o[0]||(o[0]=[s('<h1 id="numero-do-processo-no-menu-superior" tabindex="-1">Número do processo no menu superior <a class="header-anchor" href="#numero-do-processo-no-menu-superior" aria-label="Permalink to &quot;Número do processo no menu superior&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Repete o número do processo no menu superior, que fica sempre visível enquanto você rola a página. Um clique no número o copia. Quando o processo tramita em Juizado Especial, aparece ao lado um selo &quot;JESP&quot;.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, menu superior, na página do processo e no cadastro de minuta.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra um processo. O número aparece no menu superior, ao lado do seletor de perfil.</li><li>Clique no número para copiá-lo. Um efeito visual confirma a cópia.</li><li>Ao rolar a página, os avisos do topo (&quot;Segredo de Justiça&quot;, &quot;Doença Grave&quot; etc.) passam para o menu superior como pequenas etiquetas, ao lado do número ou logo abaixo dele, conforme o espaço. Ao voltar ao topo, eles retornam ao lugar original.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Mover os avisos do topo (&quot;Segredo de Justiça&quot;, &quot;Doença Grave&quot; etc.) para o menu superior ao rolar a página</td><td>ligada</td><td>Mantém os avisos à vista durante a rolagem.</td></tr><tr><td>Ocultar o número do processo no painel fixo do processo, deixando só a classe processual</td><td>desligada</td><td>Evita mostrar o número duas vezes quando o <a href="./eproc-painel-fixo-processo">Painel fixo do processo</a> também está ligado.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O selo &quot;JESP&quot; é deduzido da competência, da classe e do órgão julgador. Varas comuns com Juizado Especial anexo não recebem o selo.</li><li>Em janelas estreitas, o número pode ser cortado. Nesse caso ele volta a aparecer no painel fixo do processo, mesmo com a opção de ocultá-lo ligada.</li><li>Se as etiquetas de aviso não couberem no menu, a faixa delas rola para os lados com a roda do mouse.</li></ul>',11)]))}const h=e(t,[["render",n]]);export{m as __pageData,h as default};
